metrics.workdir_dsl:
workspace "Home Energy Management Platform" "A C4 model of the Energy Manager platform for managing household energy use and costs" {

    !identifiers hierarchical

    model {

        homeowner = person "Homeowner" "A homeowner who manages their household's energy use and costs"

        energyManager = softwareSystem "Energy Manager" "A platform for managing household energy use and costs, owned and operated by our company" {

            dashboard = container "Dashboard Web App" "A web app where homeowners see their consumption and costs. Embeds the shared Rates Library, which computes energy prices from tariff and time of day" "Web Application"

            scheduler = container "Scheduling Service" "A service that plans charging and heating. Embeds the shared Rates Library, which computes energy prices from tariff and time of day" "Background Service"

            database = container "Database" "Stores meter readings and schedules" "Relational Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "An external provider of live meter readings, operated by a different organization" "External"

        homeowner -> energyManager.dashboard "views consumption and costs" "HTTPS"
        energyManager.scheduler -> smartMeterProvider "fetches live meter readings" "HTTPS"
        energyManager.dashboard -> energyManager.database "reads meter readings and schedules from" "SQL"
        energyManager.scheduler -> energyManager.database "stores meter readings and schedules in" "SQL"
    }

    views {

        systemContext energyManager "SystemContext" "System context for the Energy Manager platform" {
            include *
            autoLayout
            title "System Context for Energy Manager"
        }

        container energyManager "Containers" "Container diagram for the Energy Manager platform" {
            include *
            autoLayout
            title "Containers for Energy Manager"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
